  goals:{protection:{name:'Pedidos suspeitos',help:'Parar e verificar antes de agir.'},access:{name:'Não perder os acessos',help:'Preparar alternativas aos acessos principais.'},family:{name:'Preparar a família',help:'Papéis e verificações compreensíveis.'},legacy:{name:'Memórias e futuro',help:'Instruções e arquivos sob o seu controlo.'},business:{name:'Continuidade do trabalho',help:'Dependências, papéis e recursos da atividade.'},ai:{name:'Permissões de apps e IA',help:'Perceber quem ou o que pode agir por si.'},complete:{name:'O percurso completo',help:'Explorar as cinco dimensões.'}},
